DO $b_selection$ DECLARE f record; BEGIN FOR f IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='private' AND p.proname IN ('require_server_combat_job','server_start_encounter')) OR (n.nspname='public' AND p.proname='select_online_job') LOOP EXECUTE replace(pg_get_functiondef(f.oid),'''contract_mercenary'',''hunter'',''field_medic'',''duelist'',''berserker''','''contract_mercenary'',''hunter'',''field_medic'',''duelist'',''berserker'',''vanguard_explorer'',''tracker'',''survivor'',''expedition_medic'',''redeemer'',''lantern_keeper'',''relic_collector'',''monster_dismantler'',''expedition_archivist'''); END LOOP; END $b_selection$;
